select
users.*
from users users

    and users.id = #{id}
    and users.nick_name like concat('%',#{nickName},'%')
    and users.avatar = #{avatar}
    and users.username = #{username}
    and users.password = #{password}
    and users.sex = #{sex}
    and users.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from users users

    and users.id = #{id}
    and users.nick_name like concat('%',#{nickName},'%')
    and users.avatar = #{avatar}
    and users.username = #{username}
    and users.password = #{password}
    and users.sex = #{sex}
    and users.create_time = #{createTime}
